public class LogTable {
    private final ConcurrentLinkedQueue<LogRecord> logQueue = new ConcurrentLinkedQueue<>();
    private final AtomicBoolean isProcessing = new AtomicBoolean(false);

    public void addMessage(final LogRecord lr) {
        logQueue.add(lr);
        if (!isProcessing.getAndSet(true)) {
            new Thread(() -> {
                while (!logQueue.isEmpty()) {
                    LogRecord record = logQueue.poll();
                    if (record != null) {
                        processLogRecord(record);
                    }
                }
                isProcessing.set(false);
            }).start();
        }
    }

    private void processLogRecord(LogRecord record) {
        // Process the log record here
        System.out.println(record.getMessage());
    }
}

