public class BucketList {
    private Bucket head;

    public void insertBefore(Bucket bucket, Bucket newBucket) {
        if (head == null) {
            head = newBucket;
        } else if (head == bucket) {
            newBucket.setNext(head);
            head = newBucket;
        } else {
            Bucket current = head;
            while (current.getNext() != null && current.getNext() != bucket) {
                current = current.getNext();
            }
            if (current.getNext() != null) {
                newBucket.setNext(current.getNext());
                current.setNext(newBucket);
            }
        }
    }

    public void printList() {
        Bucket current = head;
        while (current != null) {
            System.out.println(current.getName());
            current = current.getNext();
        }
    }

    public static void main(String[] args) {
        BucketList list = new BucketList();
        Bucket bucket1 = new Bucket("Bucket1");
        Bucket bucket2 = new Bucket("Bucket2");
        Bucket bucket3 = new Bucket("Bucket3");

        list.head = bucket1;
        bucket1.setNext(bucket2);

        list.insertBefore(bucket2, bucket3);

        list.printList();
    }
