public class TimeRangeSplitter {

    private static final long FETCH_DATA_DURATION = 3600000; // 1 hour in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentTime = start;

        while (currentTime < end) {
            long nextTime = Math.min(currentTime + FETCH_DATA_DURATION, end);
            timeRanges.add(new TimeRange(currentTime, nextTime));
            currentTime = nextTime;
        }

        return timeRanges;
    }

    public static void main(String[] args) {
        TimeRangeSplitter splitter = new TimeRangeSplitter();
        List<TimeRange> ranges = splitter.buildTimeRanges(0, 10000000);
        for (TimeRange range : ranges) {
            System.out.println(range);
        }
    }
}

