import java.net.URI;
import java.net.URISyntaxException;
import java.util.ArrayList;
import java.util.List;

public class PathDecoder {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> segments = new ArrayList<>();
        String path = u.getPath();
        if (path != null) {
            if (path.startsWith("/")) {
                path = path.substring(1);
            }
            String[] parts = path.split("/");
            for (String part : parts) {
                if (decode) {
                    part = decodeURIComponent(part);
                }
                segments.add(new PathSegmentImpl(part));
            }
        }
        return segments;
    }

    private static String decodeURIComponent(String s) {
        try {
            return java.net.URLDecoder.decode(s, "UTF-8");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public static class PathSegmentImpl {
        private String value;

        public PathSegmentImpl(String value) {
            this.value = value;
        }

        public String getValue() {
            return value;
        }

        @Override
        public String toString() {
            return value;
        }
    }

    public static void main(String[] args) {
        try {
            URI uri = new URI("http://example.com/path/to/resource");
            List<PathSegmentImpl> segments = decodePath(uri, true);
            for (PathSegmentImpl segment : segments) {
                System.out.println(segment);
            }
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
    }
}

