public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    Vector2D center = box.getCenter();
    double halfWidth = box.getWidth() / 2;
    Box2D box1 = new Box2D(center.getX() - halfWidth, center.getY(), halfWidth, box.getHeight());
