import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class UnescapeJava {
    private static final Pattern SLASH_N_PATTERN = Pattern.compile("\\\\n");
    private static final Pattern SLASH_T_PATTERN = Pattern.compile("\\\\t");
    private static final Pattern SLASH_B_PATTERN = Pattern.compile("\\\\b");
    private static final Pattern SLASH_F_PATTERN = Pattern.compile("\\\\f");
    private static final Pattern SLASH_R_PATTERN = Pattern.compile("\\\\r");
    private static final Pattern SLASH_QUOTE_PATTERN = Pattern.compile("\\\\\"");
    private static final Pattern SLASH_BACKSLASH_PATTERN = Pattern.compile("\\\\\\\\");

    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        str = SLASH_BACKSLASH_PATTERN.matcher(str).replaceAll("\\\\");
        str = SLASH_QUOTE_PATTERN.matcher(str).replaceAll("\"");
        str = SLASH_N_PATTERN.matcher(str).replaceAll("\n");
        str = SLASH_T_PATTERN.matcher(str).replaceAll("\t");
        str = SLASH_B_PATTERN.matcher(str).replaceAll("\b");
        str = SLASH_F_PATTERN.matcher(str).replaceAll("\f");
        str = SLASH_R_PATTERN.matcher(str).replaceAll("\r");

        return str;
    }

    public static void main(String[] args) {
        try {
            System.out.println(unescapeJava("\\\\n")); // Should print "\n"
            System.out.println(unescapeJava("\\\\t")); // Should print "\t"
            System.out.println(unescapeJava("\\\\b")); // Should print "\b"
            System.out.println(unescapeJava("\\\\f")); // Should print "\f"
            System.out.println(unescapeJava("\\\\r")); // Should print "\r"
            System.out.println(unescapeJava("\\\\\"")); // Should print "\""
            System.out.println(unescapeJava("\\\\\\\\")); // Should print "\\"
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

