    protected int removeUnusedNodes() {
        Iterator<CategoryNode> iterator = nodes.iterator();
        int removedCount = 0;

        while (iterator.hasNext()) {
            CategoryNode node = iterator.next();
            if (!node.isActive()) {
                iterator.remove();
                removedCount++;
            }
        }

        return removedCount;
    }
}

