public class TourTransformer {

    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour.isEmpty()) {
            return null;
        }

        V startVertex = null;
        for (E edge : tour) {
            startVertex = graph.getEdgeSource(edge);
            break;
        }

        GraphPath<V, E> path = new GraphWalk<>(graph, startVertex, startVertex);
        Iterator<E> iterator = tour.iterator();
        E previousEdge = iterator.next();
        V previousVertex = graph.getEdgeTarget(previousEdge);

        while (iterator.hasNext()) {
            E currentEdge = iterator.next();
            V currentVertex = graph.getEdgeTarget(currentEdge);
            path = path.extend(currentVertex, currentEdge);
            previousEdge = currentEdge;
            previousVertex = currentVertex;
        }

        return path;
    }
}

