            this.value = value;
            this.prev = null;
            this.next = null;
        }
    }

    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        Iterator<ListNodeImpl<E>> iterator = list.iterator();
        while (iterator.hasNext()) {
            ListNodeImpl<E> node = iterator.next();
            iterator.remove();
            addListNode(node);
        }
    }

    public Iterator<ListNodeImpl<E>> iterator() {
        return new Iterator<ListNodeImpl<E>>() {
            private ListNodeImpl<E> current = head;

            @Override
            public boolean hasNext() {
                return current != null;
            }

            @Override
            public ListNodeImpl<E> next() {
                ListNodeImpl<E> node = current;
                current = current.next;
                return node;
            }

            @Override
            public void remove() {
                if (current == null) {
                    throw new IllegalStateException();
                }
                if (current.prev != null) {
                    current.prev.next = current.next;
                } else {
                    head = current.next;
                }
                if (current.next != null) {
                    current.next.prev = current.prev;
                } else {
                    tail = current.prev;
                }
                current = current.prev;
            }
        };
    }

    public void addListNode(ListNodeImpl<E> node) {
        if (tail == null) {
            head = tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
