import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public class Graph {
    private List<Set<Integer>> adjacencyList;
    private List<Pair<Integer, Integer>> edges;

    public Graph(List<Set<Integer>> adjacencyList, List<Pair<Integer, Integer>> edges) {
        this.adjacencyList = adjacencyList;
        this.edges = edges;
    }

    private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

        for (Pair<Integer, Integer> edge : edges) {
            int u = edge.getFirst();
            int v = edge.getSecond();
            List<Pair<Integer, Integer>> separators = new ArrayList<>();

            for (int w : adjacencyList.get(u)) {
                if (w != v) {
                    List<Integer> separator = new ArrayList<>();
                    separator.add(w);
                    separators.add(new Pair<>(separator, edge));
                }
            }

            globalSeparatorList.add(new Pair<>(separators, edge));
        }

        return globalSeparatorList;
    }

    public static void main(String[] args) {
        // Example usage
        List<Set<Integer>> adjacencyList = new ArrayList<>();
        adjacencyList.add(Set.of(1, 2));
        adjacencyList.add(Set.of(0, 2));
        adjacencyList.add(Set.of(0, 1));

        List<Pair<Integer, Integer>> edges = new ArrayList<>();
        edges.add(new Pair<>(0, 1));
        edges.add(new Pair<>(0, 2));
        edges.add(new Pair<>(1, 2));

        Graph graph = new Graph(adjacencyList, edges);
        List<Pair<List<Pair<Integer, Integer>>, E>> result = graph.computeGlobalSeparatorList();

        // Print the result
        for (Pair<List<Pair<Integer, Integer>>, E> pair : result) {
            System.out.println("Edge: " + pair.getSecond() + ", Separators: " + pair.getFirst());
        }
    }
}

