import java.io.IOException;

public class ProtocolMessageParser {
    private byte[] buffer;
    private int position;
    private int limit;

    public ProtocolMessageParser(byte[] buffer, int limit) {
        this.buffer = buffer;
        this.position = 0;
        this.limit = limit;
    }

    public int readTag() throws IOException {
        if (position >= limit) {
            return 0;
        }
        int firstByte = buffer[position++] & 0xFF;
        if (firstByte == 0) {
            return 0;
        }
        int tag = firstByte & 0x7F;
        int shift = 7;
        while ((firstByte & 0x80) != 0) {
            if (position >= limit) {
                throw new IOException("Unexpected end of input while reading tag");
            }
            firstByte = buffer[position++] & 0xFF;
            tag |= (firstByte & 0x7F) << shift;
            shift += 7;
        }
        return tag;
    }
}

